import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/github-watch-menu.png",s="/nada-documentation/images/github-watch-custom.png",g=JSON.parse('{"title":"Community","description":"","frontmatter":{},"headers":[],"relativePath":"intro/community.md","filePath":"intro/community.md","lastUpdated":1786379412000}'),i={name:"intro/community.md"};function l(h,t,d,u,c,m){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to &quot;Community&quot;">​</a></h1><p>Use the <a href="https://github.com/ihsn/nada" target="_blank" rel="noreferrer">NADA GitHub repository</a> to follow releases, report problems, and suggest improvements.</p><h2 id="get-notifications-from-github" tabindex="-1">Get notifications from GitHub <a class="header-anchor" href="#get-notifications-from-github" aria-label="Permalink to &quot;Get notifications from GitHub&quot;">​</a></h2><p>GitHub can notify you about activity on the NADA repository, including new releases.</p><ol><li>Open <a href="https://github.com/ihsn/nada" target="_blank" rel="noreferrer">https://github.com/ihsn/nada</a>.</li><li>Click <strong>Watch</strong> near the top of the page (it may show <strong>Unwatch</strong> if you already follow the repository).</li><li>Choose <strong>All Activity</strong>.</li></ol><p><img src="'+n+'" alt="GitHub Watch menu on the NADA repository, with All Activity selected"></p><p>This is the simplest option: you will be notified about releases, issues, pull requests, and other repository activity.</p><p>If you only want emails about new NADA versions, choose <strong>Custom</strong> in the same menu, select <strong>Releases</strong>, then click <strong>Apply</strong>.</p><p><img src="'+s+'" alt="GitHub Custom watch options, including Releases"></p><p>You can change or turn off Watch settings at any time from the Watch menu.</p><h3 id="star-vs-watch" tabindex="-1">Star vs Watch <a class="header-anchor" href="#star-vs-watch" aria-label="Permalink to &quot;Star vs Watch&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Watch → All Activity</strong></td><td>Notifies you about releases and other repository activity (easiest option)</td></tr><tr><td><strong>Watch → Custom → Releases</strong></td><td>Notifies you only when a new version is published</td></tr><tr><td><strong>Star</strong></td><td>Bookmarks the repository on your GitHub account. It does <strong>not</strong> send emails</td></tr></tbody></table><h2 id="releases-and-downloads" tabindex="-1">Releases and downloads <a class="header-anchor" href="#releases-and-downloads" aria-label="Permalink to &quot;Releases and downloads&quot;">​</a></h2><p>Published versions, release notes, and downloadable packages are listed on the <a href="https://github.com/ihsn/nada/releases" target="_blank" rel="noreferrer">NADA releases page</a>.</p><h2 id="report-a-bug" tabindex="-1">Report a bug <a class="header-anchor" href="#report-a-bug" aria-label="Permalink to &quot;Report a bug&quot;">​</a></h2><p>If something does not work as expected:</p><ol><li>Check <a href="https://github.com/ihsn/nada/issues" target="_blank" rel="noreferrer">existing issues</a> to see if it was already reported.</li><li>Open a <a href="https://github.com/ihsn/nada/issues/new" target="_blank" rel="noreferrer">new issue</a> on GitHub.</li><li>Include the NADA version, your environment (OS, PHP, database), and steps to reproduce the problem.</li></ol><h2 id="suggest-a-feature" tabindex="-1">Suggest a feature <a class="header-anchor" href="#suggest-a-feature" aria-label="Permalink to &quot;Suggest a feature&quot;">​</a></h2><p>To propose an enhancement or new capability, open a <a href="https://github.com/ihsn/nada/issues/new" target="_blank" rel="noreferrer">GitHub issue</a> and describe:</p><ul><li>The problem you are trying to solve</li><li>Who would benefit</li><li>Any ideas for how it could work</li></ul><p>Clear use cases help maintainers prioritize requests.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>Improvements to this documentation site are welcome in the <a href="https://github.com/ihsn/nada-documentation" target="_blank" rel="noreferrer">nada-documentation</a> repository — including fixes, clarifications, and new examples.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>You can also contact the NADA team at <a href="mailto:datatools@worldbank.org" target="_blank" rel="noreferrer">datatools@worldbank.org</a>.</p>',25)])])}const b=e(i,[["render",l]]);export{g as __pageData,b as default};
